mk(M,"toy-joy","solid-shapes-faces-edges-corners","Solid shapes: faces, edges and corners","திடவடிவங்கள்: முகங்கள், விளிம்புகள், மூலைகள்",
 ["Name common solid shapes","Count faces, edges and corners of a cube"],
 ("The toy shop","In the toy shop Soni saw a ball, a dice, a drum and a party hat.\n\"They are all different shapes,\" she said. The shopkeeper smiled. \"Let us name them.\""),
 ["Solid shapes take up space and we can hold them. A ball is a sphere. A dice is a cube. A drum is a cylinder. A party hat is a cone.","A flat side of a solid is a face. Where two faces meet is an edge. Where edges meet is a corner. A cube has 6 faces, 12 edges and 8 corners.","A sphere has no corners and no edges, so it rolls. A cube has flat faces, so it can be stacked."],
 ["sphere","cube","cylinder","cone","face","edge","corner"],
 [("A ball is a sphere. A dice is a cube.","sphere, cube"),("A drum is a cylinder. A party hat is a cone.","cylinder, cone"),("A cube has 6 faces, 12 edges and 8 corners.","cube: 6, 12, 8"),("A sphere rolls because it has no flat faces.","sphere rolls")],
 ("How many faces does a dice have?",[("A dice is a cube.","Name the shape."),("A cube has 6 flat faces.","Count the sides."),("So the dice has 6 faces.","The answer is 6.")]),
 ("A friend says a ball has corners. How will you reply?",["A ball is a sphere.","A sphere has no corners."],["Thinking all solids have corners."]),
 ["Solids: sphere, cube, cylinder, cone.","Face, edge, corner.","A cube has 6 faces, 12 edges, 8 corners."],
 qs("s",[("m","A dice has the shape of a","cube","sphere","cone","A dice is a cube."),("t","A ball is a sphere.",True,"Yes."),("m","A cube has how many faces?","6","4","8","6 faces."),("t","A sphere has corners.",False,"No corners."),("m","A party hat is a","cone","cube","cylinder","Cone."),("s","How many corners does a cube have? Write only the number.",["8","eight"],"8 corners."),("m","A drum is a","cylinder","cone","sphere","Cylinder."),("t","A cube has 12 edges.",True,"Yes.")]))
mk(M,"double-century","numbers-100-to-200","Numbers from 100 to 200","100 முதல் 200 வரை எண்கள்",
 ["Read and write numbers up to 200","Find the number before and after"],
 ("Runs in a match","Avi's team scored 100 runs. The next day the team scored 100 more.\n\"Now we have 200!\" he shouted. \"A double century!\""),
 ["After 99 comes 100. Ten tens make one hundred. Numbers after 100 are 101, 102 and so on up to 200, which is two hundred.","In 138 the digit 1 is in the hundreds place, 3 is in the tens place and 8 is in the ones place. So 138 is 100 plus 30 plus 8.","The number before 150 is 149 and the number after 150 is 151. We can also count in tens: 100, 110, 120, 130, and so on."],
 ["hundred","tens","ones","before","after"],
 [("Ten tens make one hundred.","100"),("138 is 100 plus 30 plus 8.","138 = 100 + 30 + 8"),("Before 150 is 149. After 150 is 151.","before and after"),("Count in tens: 100, 110, 120, 130.","counting in tens")],
 ("Write 175 as hundreds, tens and ones.",[("The digit 1 is in the hundreds place: 100.","Hundreds."),("The digit 7 is in the tens place: 70. The digit 5 is in the ones place: 5.","Tens and ones."),("So 175 is 100 plus 70 plus 5.","Expanded form.")]),
 ("A friend says 200 comes right after 99. How will you reply?",["After 99 comes 100.","200 comes after 199."],["Skipping numbers."]),
 ["Ten tens make 100.","Place value: hundreds, tens, ones.","Find the number before and after."],
 qs("c",[("m","How many tens make 100?","10","5","100","Ten tens."),("t","After 99 comes 100.",True,"Yes."),("m","The number after 149 is","150","148","159","Add one."),("t","138 is 100 plus 30 plus 8.",True,"Yes."),("m","In 175 the digit 7 is in the ___ place.","tens","ones","hundreds","7 tens."),("s","What number comes just before 120? Write only the number.",["119"],"119."),("m","Count in tens: 100, 110, 120, ...","130","121","140","Add 10."),("t","200 is two hundred.",True,"Yes.")]))
mk(M,"vacation-with-my-nani-maa","adding-and-subtracting-up-to-200","Adding and subtracting up to 200","200 வரை கூட்டலும் கழித்தலும்",
 ["Add numbers up to 200","Subtract numbers up to 200"],
 ("Mangoes at Nani Maa's house","Soni picked 45 mangoes from one tree and 38 from another.\n\"How many mangoes altogether?\" asked Nani Maa. \"Let us add,\" said Soni."),
 ["To add, line up ones under ones and tens under tens. Add the ones first. 45 plus 38: 5 plus 8 is 13, so write 3 and carry 1 ten. Then 4 tens plus 3 tens plus 1 ten is 8 tens. The answer is 83.","To subtract, take away from the bigger number. 83 minus 38: we cannot take 8 from 3, so borrow 1 ten. 13 minus 8 is 5 and 7 tens minus 3 tens is 4 tens. The answer is 45.","Word problems: altogether means add. How many are left means subtract. Check by doing the opposite operation."],
 ["add","subtract","carry","borrow","altogether"],
 [("To add, add the ones first, then the tens.","add ones then tens"),("45 plus 38 is 83. We carry 1 ten.","45 + 38 = 83"),("To subtract, borrow a ten when needed.","borrow"),("83 minus 38 is 45. Check by adding back.","83 - 38 = 45")],
 ("Soni has 83 mangoes and gives away 38. How many are left?",[("Left means subtract: 83 minus 38.","Choose subtract."),("Borrow a ten: 13 minus 8 is 5, then 7 minus 3 is 4.","Do the sum."),("So 45 mangoes are left.","Check: 45 plus 38 is 83.")]),
 ("A friend says 45 plus 38 is 73. How will you check?",["Add the ones: 5 plus 8 is 13.","Carry 1 ten, so the answer is 83."],["Forgetting to carry."]),
 ["Add ones first, carry if needed.","Subtract, borrow if needed.","Altogether means add; left means subtract."],
 qs("a",[("m","45 plus 38 is","83","73","82","Carry a ten."),("t","Altogether means we add.",True,"Yes."),("m","83 minus 38 is","45","55","51","Borrow a ten."),("t","We can check subtraction by adding back.",True,"Yes."),("m","20 plus 30 is","50","40","60","2 tens + 3 tens."),("s","What is 100 minus 40? Write only the number.",["60"],"60."),("m","How many are left means we","subtract","add","count","Subtract."),("t","10 plus 10 plus 10 is 40.",False,"It is 30.")]))
mk(M,"fun-at-class-party","units-of-length","Units of length","நீளத்தின் அலகுகள்",
 ["Know why we use standard units","Measure in centimetres and metres"],
 ("The ribbon","For the class party Avi measured a ribbon with his hand. It was 8 hands long. Soni measured it with her hand and got 10 hands.\n\"Why are they different?\" they asked. \"Because our hands are different sizes,\" said the teacher. \"We need a standard unit.\""),
 ["A standard unit is the same for everybody. A centimetre (cm) measures small lengths like a pencil. A metre (m) measures longer lengths like a room. A kilometre (km) measures long distances like the way between towns.","100 centimetres make 1 metre. 1000 metres make 1 kilometre. A ruler is used to measure in centimetres.","To measure with a ruler, start at the zero mark and read the number where the object ends."],
 ["centimetre","metre","kilometre","ruler","standard unit"],
 [("Hands and feet change from person to person. We use standard units.","standard units"),("Use centimetres for small things and metres for longer things.","cm and m"),("100 centimetres make 1 metre.","100 cm = 1 m"),("1000 metres make 1 kilometre.","1000 m = 1 km")],
 ("How many centimetres are in 2 metres?",[("1 metre is 100 centimetres.","Remember the fact."),("2 metres is 100 plus 100.","Add."),("So 2 metres is 200 centimetres.","200 cm.")]),
 ("A friend measures with a hand and says the table is 5 hands. Why is this not enough?",["Hands are of different sizes.","We use cm and m so everyone gets the same answer."],["Using body parts only."]),
 ["Standard units are the same for all.","100 cm = 1 m; 1000 m = 1 km.","Start from zero on the ruler."],
 qs("l",[("m","How many centimetres make 1 metre?","100","10","1000","100 cm."),("t","A ruler measures in centimetres.",True,"Yes."),("m","The distance between two towns is measured in","kilometres","centimetres","grams","Long distance."),("t","Hands are standard units.",False,"They differ."),("m","A pencil is measured in","centimetres","kilometres","litres","Small length."),("s","How many metres make 1 kilometre? Write only the number.",["1000"],"1000 m."),("m","Where do we place the start of the object on a ruler?","at zero","at 5","anywhere","Start at zero."),("t","2 metres is 200 centimetres.",True,"Yes.")]))
mk(M,"the-surajkund-fair","patterns-and-symmetry","Patterns and symmetry","வடிவங்களும் சமச்சீரும்",
 ["Continue a pattern","Spot symmetry in a shape"],
 ("The craft fair","At the Surajkund fair Soni saw a cloth with a border: red, blue, red, blue, red, blue.\n\"What comes next?\" asked her grandmother. \"Red!\" said Soni."),
 ["A pattern repeats in a fixed way. Colours, shapes and numbers can make patterns. Red, blue, red, blue is a pattern of two colours. To continue a pattern, find the part that repeats.","A shape is symmetrical if one half is the mirror of the other half. A butterfly and a leaf are nearly symmetrical. If we fold a symmetrical shape along the middle line, both halves fit exactly.","Rangoli, borders on cloth and tiles use patterns and symmetry. We can make our own pattern with shapes and colours."],
 ["pattern","symmetry","fold","mirror"],
 [("A pattern repeats in a fixed way.","pattern"),("Red, blue, red, blue. Next is red.","red, blue, red, blue, ...red"),("A symmetrical shape has two halves that match.","symmetry"),("Fold along the middle line. Both halves fit.","fold test")],
 ("Which comes next: circle, square, circle, square, circle?",[("The repeating part is circle, square.","Find the unit."),("After a circle comes a square.","Follow the rule."),("So next is a square.","The pattern continues.")]),
 ("A friend says every shape is symmetrical. How will you reply?",["A symmetrical shape folds into two matching halves.","Some shapes do not."],["Assuming all shapes are symmetrical."]),
 ["A pattern repeats.","To continue it, find the repeating part.","Symmetry means two matching halves."],
 qs("p",[("m","Red, blue, red, blue, red, ...","blue","red","green","Alternate."),("t","A pattern repeats.",True,"Yes."),("m","A symmetrical shape has two halves that","match","are different","do not fit","Mirror halves."),("t","A butterfly is nearly symmetrical.",True,"Yes."),("m","Next in 1, 2, 1, 2, 1, ...","2","1","3","Repeat."),("s","In 2, 4, 6, 8 what comes next? Write only the number.",["10"],"Add 2."),("m","To test symmetry we","fold the shape","cut it","paint it","Fold test."),("t","Rangoli can use patterns.",True,"Yes.")]))
