mk(E,"making-things","how-things-are-made","How things are made","பொருட்கள் எவ்வாறு செய்யப்படுகின்றன",
 ["Describe how a clay pot is made","Say who makes things for us"],
 ("The potter","Next to the school lived a potter. Every day he shaped wet clay on a wheel, dried the pots in the sun and baked them in a kiln.\nRani watched him closely. \"A lump of mud becomes a pot,\" she said."),
 ["Many things we use are made by people. Potters make pots, weavers make cloth, carpenters make furniture, tailors stitch clothes and cooks make food.","A clay pot is made in steps: dig and clean the clay, mix it with water, shape it on a wheel, dry it in the sun and bake it in a kiln. The steps must be in order.","People who make things use skill and tools. We should respect their work, use things carefully and make things with our own hands too."],
 ["potter","weaver","kiln","tool"],
 [("People make many things: pots, cloth, furniture and clothes.","makers"),("A pot is made from clay, shaped on a wheel, dried and baked.","making a pot"),("The steps must be in order.","order"),("Respect people who make things.","respect makers")],
 ("Put these in order: bake the pot, shape the clay, dig clay.",[("First dig the clay.","Step 1."),("Then shape it on a wheel.","Step 2."),("Last, bake it.","Step 3.")]),
 ("A friend says things just appear in shops. How will you reply?",["People make them with skill.","They use tools and steps."],["Not valuing makers."]),
 ["People make things using skill and tools.","A clay pot is made in steps.","Respect makers."],
 qs("k",[("m","A person who makes pots is a","potter","tailor","driver","Potter."),("t","A pot is baked in a kiln.",True,"Yes."),("m","A weaver makes","cloth","pots","bricks","Cloth."),("t","The steps of making a pot can be in any order.",False,"They are in order."),("m","A carpenter makes","furniture","cloth","food","Furniture."),("s","What is a pot made of? Write one word.",["clay","mud"],"Clay."),("m","We should","respect makers","laugh at makers","ignore makers","Respect."),("t","Tools help people make things.",True,"Yes.")]))
